import{z as l,x as t,o as e,c as s,q as A,j as n,D as a,d as r,s as o,S as i}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"健康政策的因果证据","description":"","frontmatter":{"title":"健康政策的因果证据","date":"2026-09-18T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/ca-health-policy-evidence.md","filePath":"econ/ca-health-policy-evidence.md","lastUpdated":1791413859000}'),d={name:"econ/ca-health-policy-evidence.md"};function c(p,E,h,D,C,T){const B=t("Mermaid");return e(),s("div",null,[E[2]||(E[2]=A('<h1 id="健康政策的因果证据" tabindex="-1">健康政策的因果证据 <a class="header-anchor" href="#健康政策的因果证据" aria-label="Permalink to &quot;健康政策的因果证据&quot;">​</a></h1><div class="epigraph"><p>在健康领域，「有效」与「被使用」之间隔着一条支付与选择的缝，因果推断的全部工作都铺在这条缝上。</p><footer>—— 据 Newhouse and the Insurance Experiment Group, Free for All?, 1993；Finkelstein 等, QJE 2012 整理</footer></div><p><a href="/econ/ca-labor-policy-evidence">上一课</a>在劳动政策里数了法条留下的缝。本课到健康政策：这里的缝开在保险、年龄与地理上，而且健康是极少数拥有两代大型随机实验的社会科学领域。链条「保险 → 医疗利用 → 健康」有三段，每段一个识别陷阱：选择进入保险（<a href="/econ/hi-risk-selection">风险选择与 Rothschild–Stiglitz 的深化</a>）、价格改变利用量（<a href="/econ/hi-demand-moralhazard">保险的需求与道德风险</a>）、利用量不等于健康。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>观察性证据在这里全面失真：买保险的人病得更重，用它估「保险致病的利用量」会把需求与风险混在一起；用参保者与未参保者比健康，估到的又是选择。<a href="/econ/hi-demand-moralhazard">道德风险</a>课的静态模型给了方向，但政策问的是量：自付比例降低一档，支出与利用量动多少？动的是该动的还是浪费？扩保救不救人？健康政策的因果问题因此拆成三个：保险对利用的效应、利用对健康的效应、以及前者在多大程度上经由后者兑现。</p><p><span class="marginnote">道德风险就是「看病变便宜了，于是多用」——不是骗保，是价格变化后的正常反应。它本身不全是坏事：该看没看的病这回看了。政策要算的是多出来的那部分里，多少买到了有用的医疗，多少只是零价格的浪费，这正是兰德实验要量的事。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>四条缝各配一个设计。<strong>价格缝，随机</strong>：兰德医保实验（1971–1986）把约两千七百户家庭分进 0/25/50/95% 共保率四档，免费档的支出比 95% 档高约四成，健康结局对多数人几乎没差——道德风险是真的，但它的福利代价主要落在浪费上。<strong>资格缝，抽签</strong>：俄勒冈 2008 年对 Medicaid 名额抽签，近九万人报名争约一万个名额，抽签即随机化；参保率升约 25 个百分点是第一阶段，结局沿 ITT 报（Finkelstein 等 2012）：医疗利用与自报健康改善，财务压力显著下降，抑郁下降——这些正是<a href="/econ/pe-rct-design-analysis">RCT 的设计与分析</a>里设计契约的兑现。<strong>年龄缝，断点</strong>：65 岁医保资格线上，覆盖率与利用量跳升、健康只微动（Card–Dobkin–Ma 2008）。<strong>地理缝，工具</strong>：心梗老人的激进治疗效应，用「到最近有导管室的医院的路程」做工具，把 OLS 里病人被送往大医院的选择偏误剥掉（McClellan–McNeil–Newhouse 1994）。</p><p><span class="marginnote">兰德的四档可以想成四组购物车：药价越贵，购物车越空。自付 0% 的免费档比 95% 档多花了约四成医疗费，多数人的健康却没见好——多花的钱大头买了「多看」，没买来「更健康」。这就是道德风险的量：存在，但福利代价主要在浪费端。</span></p>',9)),(e(),n(i,null,{default:a(()=>[o(B,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20INS%5B%22%E4%BF%9D%E9%99%A9%22%5D%20--%3E%7C%E4%BB%B7%E6%A0%BC%E6%95%88%E5%BA%94%7C%20UTIL%5B%22%E5%8C%BB%E7%96%97%E5%88%A9%E7%94%A8%22%5D%0A%20%20UTIL%20--%3E%7C%E6%8A%80%E6%9C%AF%E8%BE%B9%E9%99%85%7C%20HEALTH%5B%22%E5%81%A5%E5%BA%B7%22%5D%0A%20%20INS%20--%3E%7C%E9%80%89%E6%8B%A9%7C%20SEL%5B%22%E7%97%85%E4%BA%BA%E6%9C%AC%E6%9D%A5%E5%B0%B1%E6%9B%B4%E7%97%85%22%5D%0A%20%20SEL%20--%3E%7C%E6%B1%A1%E6%9F%93%20OLS%7C%20UTIL%0A%20%20RCT%5B%22%E5%85%B0%E5%BE%B7%EF%BC%9A%E4%BB%B7%E6%A0%BC%E7%BC%9D%E9%9A%8F%E6%9C%BA%22%5D%20--%3E%20INS%0A%20%20LOT%5B%22%E4%BF%84%E5%8B%92%E5%86%88%EF%BC%9A%E8%B5%84%E6%A0%BC%E7%BC%9D%E6%8A%BD%E7%AD%BE%22%5D%20--%3E%20INS%0A%20%20RDD%5B%2265%20%E5%B2%81%E6%96%AD%E7%82%B9%22%5D%20--%3E%20INS%0A%20%20IV%5B%22%E8%B7%AF%E7%A8%8B%E5%B7%A5%E5%85%B7%22%5D%20--%3E%20UTIL%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[r(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=A('<p><span class="marginnote">兰德实验的口径常被报反：免费档支出高约四成，是相对 95% 共保档；「健康没差」说的是平均，最穷最病的一组（高血压、视力、牙科）确有改善。平均效应掩盖分层效应，这是把 RCT 读成一句话的代价。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>为什么健康领域的证据这样长在缝隙上：没有人能随机分配疾病，但制度在「谁被覆盖、以什么价格、从哪一岁开始」上反复重切人群，每次重切都是一次准实验。机制的两头都要记账：一头是道德风险与保险价值的权衡——<a href="/econ/pe-case-map">俄勒冈的案例</a>里，「有保险」到「健康」的链条被分段评估，财务与抑郁的改善先兑现，死亡率的效应测不出（置信区间宽，样本撑不起）；另一头是 LATE 的口径：俄勒冈估的是「新获保的低收入无保成人」的效应，把它外推到全民覆盖，就犯了<a href="/econ/pe-external-validity">外部有效性</a>课警告的搬运错误。不这么做会错在哪：用参保者-未参保者之差，估到的是选择不是因果；用利用率当健康结果，会把「多看病」读成「更健康」。</p>',3)),(e(),n(i,null,{default:a(()=>[o(B,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20LOT%5B%22%E4%BF%84%E5%8B%92%E5%86%88%3A%20%E8%BF%91%209%20%E4%B8%87%E4%BA%BA%E6%8A%BD%E7%BA%A6%201%20%E4%B8%87%E4%B8%AA%E5%90%8D%E9%A2%9D%22%5D%20--%3E%20W%5B%22%E4%B8%AD%E7%AD%BE%E7%BB%84%22%5D%0A%20%20LOT%20--%3E%20N%5B%22%E6%9C%AA%E4%B8%AD%E7%AD%BE%E7%BB%84%3A%20%E5%A4%A9%E7%84%B6%E5%AF%B9%E7%85%A7%22%5D%0A%20%20W%20--%3E%20F%5B%22%E7%AC%AC%E4%B8%80%E9%98%B6%E6%AE%B5%3A%20%E5%8F%82%E4%BF%9D%E7%8E%87%E5%8D%87%E7%BA%A6%2025pp%22%5D%0A%20%20F%20--%3E%20O%5B%22%E7%BB%93%E5%B1%80%E6%8C%89%20ITT%20%E6%8A%A5%3A%20%E5%88%A9%E7%94%A8%E4%B8%8E%E8%87%AA%E6%8A%A5%E5%81%A5%E5%BA%B7%E6%94%B9%E5%96%84%2C%20%E6%8A%91%E9%83%81%E4%B8%8B%E9%99%8D%22%5D%0A%20%20N%20--%3E%20O%0A%20%20O%20--%3E%20M%5B%22%E6%AD%BB%E4%BA%A1%E7%8E%87%3A%20%E5%8C%BA%E9%97%B4%E5%A4%AA%E5%AE%BD%2C%20%E6%B5%8B%E4%B8%8D%E5%87%BA%22%5D%0A%20%20F%20--%3E%20LATE%5B%22LATE%20%E5%8F%A3%E5%BE%84%3A%20%E8%AF%BB%E6%95%B0%E5%B1%9E%E4%BA%8E%E6%96%B0%E8%8E%B7%E4%BF%9D%E7%9A%84%E4%BD%8E%E6%94%B6%E5%85%A5%E6%97%A0%E4%BF%9D%E6%88%90%E4%BA%BA%22%5D%0A%20%20LATE%20--%3E%20X%5B%22%E7%9B%B4%E6%8E%A5%E5%A4%96%E6%8E%A8%E5%88%B0%E5%85%A8%E6%B0%91%E8%A6%86%E7%9B%96%20%3D%20%E6%90%AC%E8%BF%90%E9%94%99%E8%AF%AF%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[r(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=A('<p><span class="marginnote">抽签为什么等于随机化：名额远少于报名人数（约一万个名额、近九万人报名），谁中签像抛硬币，两组人连「想不想参保」的劲头都来自同一个池子。于是「中签」成了纯净的分配器——比较中签与未中签，就在比较运气，而不是比较健康。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>死亡率为结局的实验天然缺功效：效应小、时滞长，需要数十万人年的样本，所以两代实验都只够对中等强度的中间结局下结论；利用量与健康的距离，正是药品定价与价值评估课要接的问题。供给侧反应也要进账：扩保抬需求，若供给不弹性，排队与等待会把账面覆盖变成账面等待。本课不重讲保险结构——筛选与<a href="/econ/hi-demand-moralhazard">道德风险</a>的理论在健康与保险课里已经拆过；这里的增量是：那些理论参数，是靠哪些缝隙被量出来的。</p><p><span class="marginnote">这一步如果只读需求端会错在哪：扩保等于往医疗系统里一次性放进几十万新顾客，若医生和床位不跟着涨，账面上「人人在保」，现实中是排队变长——覆盖是名义的，等待是真实的。读任何扩保评估，都要同时盯需求与供给两本账。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>健康政策的因果链条三段：保险 → 利用 → 健康，每段一个识别陷阱。</li><li>四条缝四个设计：价格（兰德随机）、资格（俄勒冈抽签）、年龄（65 岁断点）、地理（路程工具）。</li><li>道德风险为真但主要在浪费端；平均效应之外要读分层效应。</li><li>LATE 口径限定外推：新获保者的效应不等于全民覆盖的效应；死亡率结局缺功效。</li><li>出处：Newhouse 等, Free for All?, 1993；Finkelstein 等, QJE 2012；Taubman 等, Science 2014；Card, Dobkin and Ma 2008；McClellan, McNeil and Newhouse, JAMA 1994。</li></ul>',6))])}const f=l(d,[["render",c]]);export{_ as __pageData,f as default};
